import torch
import torch.nn as nn
import triton
import triton.language as tl


def _ce_configs():
    configs = []
    for BN in [1024, 2048, 4096]:
        for nw in [4, 8, 16]:
            for ws in [16, 32]:
                configs.append(
                    triton.Config({"BLOCK_N": BN, "warp_size": ws}, num_warps=nw)
                )
    return configs


@triton.autotune(configs=_ce_configs(), key=["N"])
@triton.jit
def _cross_entropy_online_kernel(
    logits_ptr,
    targets_ptr,
    losses_ptr,
    N,
    stride_lm,
    stride_ln,
    BLOCK_N: tl.constexpr,
    warp_size: tl.constexpr,
):
    row = tl.program_id(0)
    row_off = row.to(tl.int64) * stride_lm

    LOG2E: tl.constexpr = 1.4426950408889634
    LN2: tl.constexpr = 0.6931471805599453

    running_max = -float("inf")
    running_sum = 0.0

    for start in range(0, N, BLOCK_N):
        col_offs = start + tl.arange(0, BLOCK_N)
        mask = col_offs < N
        x = tl.load(
            logits_ptr + row_off + col_offs * stride_ln, mask=mask, other=-float("inf")
        ).to(tl.float32)

        block_max = tl.max(x, axis=0)
        new_max = tl.maximum(running_max, block_max)

        running_sum = running_sum * tl.math.exp2(
            (running_max - new_max) * LOG2E
        ) + tl.sum(tl.math.exp2((x - new_max) * LOG2E), axis=0)
        running_max = new_max

    log_sum_exp = tl.math.log2(running_sum) * LN2

    target = tl.load(targets_ptr + row).to(tl.int64)
    target_logit = tl.load(logits_ptr + row_off + target * stride_ln).to(tl.float32)

    loss = -target_logit + running_max + log_sum_exp
    tl.store(losses_ptr + row, loss)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, predictions, targets):
        predictions = predictions.contiguous()
        targets = targets.contiguous()

        M, N = predictions.shape
        losses = torch.empty(M, device=predictions.device, dtype=torch.float32)

        grid = (M,)
        _cross_entropy_online_kernel[grid](
            predictions,
            targets,
            losses,
            N,
            predictions.stride(0),
            predictions.stride(1),
        )

        return losses.mean()


